 readable(){const svg=$('stock-map-svg');if(!svg)return;this.positionTemporary();const scale=svg.getScreenCTM()?.a||1,measure=document.createElement('canvas').getContext('2d');for(const g of svg.querySelectorAll('[data-map-cell]')){const l=StockMap.data.locations.find(l=>l.cell_code===g.dataset.mapCell);if(!l||l.map_usage==='TEMPORARY')continue;const c=StockMap.data.cells.find(c=>c.code===l.cell_code);if(!c)continue;g.querySelectorAll('text').forEach(t=>t.remove());const x=Number(c.x),y=Number(c.y),w=Number(c.width),h=Number(c.height),f=this.fields(l),line=[l.code,f.lot,f.customer,l.current.bundle_count+' 捆'].join(' | '),availableW=Math.max(0,w*scale-10),availableH=Math.max(0,h*scale-4);measure.font='700 16px sans-serif';const fullSize=Math.min(16,availableH,16*availableW/Math.max(1,measure.measureText(line).width)),fits=this.occupied(l)&&fullSize>=10;let text=fits?line:l.code,size=fits?Math.floor(fullSize):Math.min(12,Math.floor(availableH));measure.font='700 '+size+'px sans-serif';if(size>=9&&availableW>=measure.measureText(text).width){V27.text(g,x+w/2,y+h/2+size*.35/scale,text,fits?'v271-physical-count':'map-code','middle',true);const t=g.querySelector('text');t.style.fontSize=size/scale+'px';t.style.fontWeight='700';t.style.visibility='visible';t.style.display='block';}g.querySelector('title').textContent=this.occupied(l)?line:l.code;}},
