 stage.onfullscreenchange=()=>{requestAnimationFrame(()=>{this.apply();this.readable();});};canvas.onwheel=e=>{e.preventDefault();this.scale(this.zoom*Math.exp(-Math.max(-500,Math.min(500,e.deltaY))*.0015),e.clientX,e.clientY);this.readable();};
